 [("This is the ___ road.",["shortest","shorter","short"],"The shortest."),
  ("It's the ___ popular song.",["most","more","much"],"The most popular."),
  ("It's one of the ___ films.",["best","good","better"],"One of the best.")],
 ("Яка форма від hot?",["the hottest","the hotest","the most hot"],"Hot — the hottest."),
